CREATE TYPE "Health" AS ENUM ('GREEN','ORANGE','RED'); CREATE TYPE "ActionStatus" AS ENUM ('TODO','IN_PROGRESS','BLOCKED','DONE','CANCELLED'); CREATE TYPE "Priority" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL'); CREATE TYPE "EventType" AS ENUM ('COMMITTEE','MEETING','MILESTONE','ACTION','DECISION','RISK'); CREATE TABLE "Project"("id" TEXT PRIMARY KEY,"name" TEXT UNIQUE NOT NULL,"description" TEXT,"phase" TEXT NOT NULL DEFAULT 'Cadrage',"progress" INTEGER NOT NULL DEFAULT 0,"health" "Health" NOT NULL DEFAULT 'GREEN',"color" TEXT NOT NULL DEFAULT 'sky',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE TABLE "Action"("id" TEXT PRIMARY KEY,"reference" TEXT UNIQUE NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"owner" TEXT,"dueDate" TIMESTAMP(3),"status" "ActionStatus" NOT NULL DEFAULT 'TODO',"priority" "Priority" NOT NULL DEFAULT 'MEDIUM',"source" TEXT,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE TABLE "Risk"("id" TEXT PRIMARY KEY,"reference" TEXT UNIQUE NOT NULL,"title" TEXT NOT NULL,"probability" INTEGER NOT NULL,"impact" INTEGER NOT NULL,"level" TEXT NOT NULL,"owner" TEXT,"mitigation" TEXT,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE); CREATE TABLE "Milestone"("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"dueDate" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'PLANNED',"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE); CREATE TABLE "Event"("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3),"type" "EventType" NOT NULL,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE); CREATE TABLE "TimesheetEntry"("id" TEXT PRIMARY KEY,"date" TIMESTAMP(3) NOT NULL,"activity" TEXT NOT NULL,"hours" DECIMAL(5,2) NOT NULL,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE);